1	export type Cell = [number, number];
2	
3	const key = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighboursOf = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	export function nextGeneration(liveCells: Cell[]): Cell[] {
17	  const live = new Set(liveCells.map(key));
18	  const liveNeighbourCount = (cell: Cell): number =>
19	    neighboursOf(cell).filter((neighbour) => live.has(key(neighbour))).length;
20	
21	  const candidates = new Map<string, Cell>();
22	  for (const cell of liveCells) {
23	    candidates.set(key(cell), cell);
24	    for (const neighbour of neighboursOf(cell)) {
25	      candidates.set(key(neighbour), neighbour);
26	    }
27	  }
28	
29	  const survivors: Cell[] = [];
30	  for (const [cellKey, cell] of candidates) {
31	    const count = liveNeighbourCount(cell);
32	    const isAlive = live.has(cellKey);
33	    if (isAlive ? count === 2 || count === 3 : count === 3) {
34	      survivors.push(cell);
35	    }
36	  }
37	  return survivors;
38	}
